import{Tt as e,at as t,rt as n,t as r}from"./chunks/framework.CZq4qJDD.js";var i=JSON.parse(`{"title":"2026-11-24","description":"","frontmatter":{"authorship":["ai"]},"headers":[],"relativePath":"reports/2026-11-24.md","filePath":"reports/2026-11-24.md"}`),a={name:`reports/2026-11-24.md`};function o(r,i,a,o,s,c){return e(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795521984000`},[...i[0]||=[t(`<h1 id="_2026-11-24" tabindex="-1">2026-11-24 <a class="header-anchor" href="#_2026-11-24" aria-label="Permalink to “2026-11-24”">​</a></h1><p><strong>Kỳ báo cáo:</strong> 25/10/2026–24/11/2026 <strong>Commit mốc (không bao gồm):</strong> <a href="https://github.com/notopia-uit/notopia/commit/69929a45c1878d22830b3417279c631ab69a883c" target="_blank" rel="noreferrer"><code>69929a45c187</code></a><strong>Commit cuối trên <code>main</code> (bao gồm):</strong> <a href="https://github.com/notopia-uit/notopia/commit/db8c80a424b8833dc169a838e846b0c002d59ffe" target="_blank" rel="noreferrer"><code>db8c80a424b8</code></a></p><p>Trong kỳ này, Notopia cải thiện luồng thanh toán, hoàn thiện Helm chart và chuẩn bị triển khai trên homelab. Một số luồng thanh toán đã được kiểm thử trên Stripe sandbox; config homelab vẫn đang được hoàn thiện. Báo cáo không lặp lại phần triển khai backend AI đã trình bày kỳ trước.</p><h2 id="_1-ket-qua-thuc-hien" tabindex="-1">1. Kết quả thực hiện <a class="header-anchor" href="#_1-ket-qua-thuc-hien" aria-label="Permalink to “1. Kết quả thực hiện”">​</a></h2><h3 id="_1-1-thanh-toan-va-goi-dich-vu" tabindex="-1">1.1. Thanh toán và gói dịch vụ <a class="header-anchor" href="#_1-1-thanh-toan-va-goi-dich-vu" aria-label="Permalink to “1.1. Thanh toán và gói dịch vụ”">​</a></h3><ul><li><strong>Mô hình nghiệp vụ:</strong> Tổ chức lại các kiểu dữ liệu cho tiền, thanh toán, giá, đăng ký gói và hoàn tiền để làm rõ quy tắc nghiệp vụ và tránh sửa dữ liệu ngoài ý muốn. <a href="https://github.com/notopia-uit/notopia/pull/365" target="_blank" rel="noreferrer">notopia-uit/notopia#365</a>, <a href="https://github.com/notopia-uit/notopia/commit/709bd76e" target="_blank" rel="noreferrer">dọn mã không còn dùng (<code>709bd76e</code>)</a></li><li><strong>Phát event:</strong> Áp dụng <em>transactional outbox</em> để lưu thay đổi dữ liệu và event trong cùng một giao dịch. Luồng hủy gói và gửi yêu cầu hoàn tiền cho nhà cung cấp được xử lý bất đồng bộ qua outbox. <a href="https://github.com/notopia-uit/notopia/commit/d78e47a3" target="_blank" rel="noreferrer">Commit <code>d78e47a3</code></a></li><li><strong>Checkout và hoàn tiền:</strong> Khóa theo tài khoản thanh toán của workspace khi xử lý checkout trùng; không mở lại khoản hoàn tiền đã tất toán. Đã cập nhật mã và bài kiểm thử, nhưng kịch bản checkout trùng vẫn chưa hoàn tất UAT. <a href="https://github.com/notopia-uit/notopia/commit/d78e47a3" target="_blank" rel="noreferrer">Commit <code>d78e47a3</code></a></li><li><strong>Tính năng và hạn mức:</strong> Khai báo kiểu dữ liệu rõ ràng thay vì chỉ dùng khóa chuỗi chung. <a href="https://github.com/notopia-uit/notopia/commit/f758ec9c" target="_blank" rel="noreferrer">Commit <code>f758ec9c</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/18cca64c" target="_blank" rel="noreferrer">commit <code>18cca64c</code></a></li><li><strong>API thanh toán:</strong> Đổi endpoint <code>GET /billing/workspaces/{workspaceId}/subscription</code> thành <code>GET /billing/workspaces/{workspaceId}</code> vì phản hồi gồm cả gói đăng ký và bên thanh toán. <a href="https://github.com/notopia-uit/notopia/commit/a780d8bb" target="_blank" rel="noreferrer">Commit <code>a780d8bb</code></a></li><li><strong>Cổng khách hàng Stripe:</strong> Sửa config để nêu rõ các trường khách hàng được phép cập nhật. <a href="https://github.com/notopia-uit/notopia/commit/5196957d" target="_blank" rel="noreferrer">Commit <code>5196957d</code></a></li></ul><h3 id="_1-2-kubernetes-va-trien-khai-homelab" tabindex="-1">1.2. Kubernetes và triển khai homelab <a class="header-anchor" href="#_1-2-kubernetes-va-trien-khai-homelab" aria-label="Permalink to “1.2. Kubernetes và triển khai homelab”">​</a></h3><ul><li><strong>Helm:</strong> Bổ sung thư viện chart dùng chung, chart cho các dịch vụ Notopia và thành phần tiếp nhận lưu lượng có xác thực. <a href="https://github.com/notopia-uit/notopia/pull/370" target="_blank" rel="noreferrer">notopia-uit/notopia#370</a></li><li><strong>Chuẩn bị ứng dụng:</strong> Tách lệnh migration và khởi tạo dữ liệu bắt buộc; bổ sung kiểm tra trạng thái sẵn sàng, bao gồm kết nối Kafka của search-worker và các phụ thuộc của Document. <a href="https://github.com/notopia-uit/notopia/commit/72beeadf" target="_blank" rel="noreferrer">Commit <code>72beeadf</code></a></li><li><strong>GitOps:</strong> Chuẩn bị config Flux cho các dịch vụ, cơ sở dữ liệu, Meilisearch, Valkey và các manifest chứa secret đã mã hóa. <a href="https://github.com/notopia-uit/notopia/pull/376" target="_blank" rel="noreferrer">notopia-uit/notopia#376</a></li><li><strong>CI và phát hành:</strong> Thêm kiểm tra phiên bản chart, tự động hóa phát hành và tạo bản phát hành phát triển đầu tiên. <a href="https://github.com/notopia-uit/notopia/pull/379" target="_blank" rel="noreferrer">notopia-uit/notopia#379</a>, <a href="https://github.com/notopia-uit/notopia/commit/a97d424b" target="_blank" rel="noreferrer">commit <code>a97d424b</code></a></li><li><strong>Config homelab:</strong> Bổ sung config và hướng dẫn thiết lập RustFS, webhook Stripe; một số giá trị vẫn đang được hoàn thiện. <a href="https://github.com/notopia-uit/notopia/commit/6e9f301f" target="_blank" rel="noreferrer">Commit <code>6e9f301f</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/4522f0b6" target="_blank" rel="noreferrer">commit <code>4522f0b6</code></a></li></ul><h3 id="_1-3-contract-api-va-xac-thuc-khi-phat-trien" tabindex="-1">1.3. Contract API và xác thực khi phát triển <a class="header-anchor" href="#_1-3-contract-api-va-xac-thuc-khi-phat-trien" aria-label="Permalink to “1.3. Contract API và xác thực khi phát triển”">​</a></h3><ul><li><strong>Schema yêu cầu:</strong> Tách schema tạo thư mục, ghi chú và workspace khỏi schema phản hồi để máy khách không phải gửi các trường chỉ đọc do máy chủ sinh. Đây là điều chỉnh contract API, không phải nâng phiên bản OpenAPI 3.1.2. <a href="https://github.com/notopia-uit/notopia/commit/234f7efa" target="_blank" rel="noreferrer">Commit <code>234f7efa</code></a></li><li><strong>Xác thực:</strong> Bổ sung tài khoản mẫu Authentik và config OAuth để thử API cục bộ. Config thử nghiệm bằng mật khẩu không dành cho production. <a href="https://github.com/notopia-uit/notopia/commit/a115e9d0" target="_blank" rel="noreferrer">Authentik (<code>a115e9d0</code>)</a>, <a href="https://github.com/notopia-uit/notopia/commit/17cc93ac" target="_blank" rel="noreferrer">OAuth scopes (<code>17cc93ac</code>)</a></li></ul><h3 id="_1-4-cong-cu-phat-trien-va-chat-luong-ban-dung" tabindex="-1">1.4. Công cụ phát triển và chất lượng bản dựng <a class="header-anchor" href="#_1-4-cong-cu-phat-trien-va-chat-luong-ban-dung" aria-label="Permalink to “1.4. Công cụ phát triển và chất lượng bản dựng”">​</a></h3><ul><li><strong>mise:</strong> Tách config dùng chung, config cho môi trường phát triển và config cho CI; thêm lockfile theo môi trường để cài đặt công cụ nhất quán. <a href="https://github.com/notopia-uit/notopia/commit/711a6384" target="_blank" rel="noreferrer">Commit <code>711a6384</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/201943ad" target="_blank" rel="noreferrer">commit <code>201943ad</code></a></li><li><strong>gRPC/Protobuf:</strong> Cập nhật Buf, ts-proto và thư viện gRPC/Protobuf; sinh lại mã TypeScript và cập nhật cách lưu bộ nhớ đệm của bước lint proto. <a href="https://github.com/notopia-uit/notopia/pull/391" target="_blank" rel="noreferrer">notopia-uit/notopia#391</a></li><li><strong>Đóng gói Document:</strong> Gỡ <code>inquire-shim.js</code> vì lớp tương thích này không còn cần thiết; đối chiếu cho thấy bản đóng gói không đổi khi bỏ shim. <a href="https://github.com/notopia-uit/notopia/pull/392" target="_blank" rel="noreferrer">notopia-uit/notopia#392</a></li><li><strong>Telemetry và lint:</strong> Đồng bộ các thư viện OpenTelemetry của Go và Node; bật kiểm tra kiểu với Oxlint và sửa các vấn đề được phát hiện. <a href="https://github.com/notopia-uit/notopia/pull/380" target="_blank" rel="noreferrer">notopia-uit/notopia#380</a>, <a href="https://github.com/notopia-uit/notopia/commit/891cecbe" target="_blank" rel="noreferrer">commit <code>891cecbe</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/00cd90e2" target="_blank" rel="noreferrer">commit <code>00cd90e2</code></a></li></ul><h3 id="_1-5-tai-lieu" tabindex="-1">1.5. Tài liệu <a class="header-anchor" href="#_1-5-tai-lieu" aria-label="Permalink to “1.5. Tài liệu”">​</a></h3><ul><li><strong>Cấu trúc:</strong> Sắp xếp lại tài liệu theo dịch vụ và chủ đề, bổ sung nội dung về kiến trúc, dữ liệu và triển khai. <a href="https://github.com/notopia-uit/notopia/commit/cf5840a8" target="_blank" rel="noreferrer">Commit <code>cf5840a8</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/7131befe" target="_blank" rel="noreferrer">commit <code>7131befe</code></a></li><li><strong>Tham chiếu API:</strong> Bổ sung tài liệu tham chiếu gRPC được sinh tự động và sửa lỗi hiển thị tài liệu OpenAPI khi VitePress render phía máy chủ. <a href="https://github.com/notopia-uit/notopia/commit/12bb02cf" target="_blank" rel="noreferrer">gRPC (<code>12bb02cf</code>)</a>, <a href="https://github.com/notopia-uit/notopia/commit/0df87429" target="_blank" rel="noreferrer">VitePress (<code>0df87429</code>)</a></li><li><strong>Bản xem trước:</strong> Thêm bước kiểm tra và publish bản xem trước tài liệu cho pull request. <a href="https://github.com/notopia-uit/notopia/commit/251bab99" target="_blank" rel="noreferrer">Commit <code>251bab99</code></a></li></ul><h3 id="_1-6-collaboration-va-thiet-ke-publish-workspace" tabindex="-1">1.6. Collaboration và thiết kế publish workspace <a class="header-anchor" href="#_1-6-collaboration-va-thiet-ke-publish-workspace" aria-label="Permalink to “1.6. Collaboration và thiết kế publish workspace”">​</a></h3><ul><li><strong>Lưu tài liệu trong luồng collaboration:</strong> Chờ các thao tác lưu trong hàng đợi hoàn tất và giữ trạng thái chỉnh sửa của người dùng khác khi tải lại tài liệu. <a href="https://github.com/notopia-uit/notopia/commit/c11d7019" target="_blank" rel="noreferrer">Commit <code>c11d7019</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/2273ca38" target="_blank" rel="noreferrer">commit <code>2273ca38</code></a></li><li><strong>Publish workspace:</strong> Cập nhật thiết kế; chưa triển khai tính năng trong kỳ này. <a href="https://github.com/notopia-uit/notopia/commit/fb4c5c38" target="_blank" rel="noreferrer">Commit <code>fb4c5c38</code></a>, <a href="https://github.com/notopia-uit/notopia/commit/c80f8eaa" target="_blank" rel="noreferrer">commit <code>c80f8eaa</code></a></li></ul><h2 id="_2-kiem-thu-va-tinh-trang-trien-khai" tabindex="-1">2. Kiểm thử và tình trạng triển khai <a class="header-anchor" href="#_2-kiem-thu-va-tinh-trang-trien-khai" aria-label="Permalink to “2. Kiểm thử và tình trạng triển khai”">​</a></h2><h3 id="_2-1-kiem-thu-thanh-toan" tabindex="-1">2.1. Kiểm thử thanh toán <a class="header-anchor" href="#_2-1-kiem-thu-thanh-toan" aria-label="Permalink to “2.1. Kiểm thử thanh toán”">​</a></h3><p>Kiểm thử thủ công bằng Scalar và Stripe sandbox ghi nhận kết quả mong đợi khi xem danh mục và quyền của workspace miễn phí, mua Plus theo tháng, hủy ngay kèm hoàn tiền, và chuyển từ Plus tháng sang Pro trọn đời. Chưa kiểm thử đầy đủ thanh toán trùng, phân quyền và khôi phục sau gián đoạn webhook. Các kết quả này không xác nhận luồng hoàn chỉnh trên giao diện hoặc mức độ sẵn sàng cho môi trường production.</p><p><a href="https://gist.github.com/KevinNitroG/c777cd1c79d017c3ae9122fde8ebb753" target="_blank" rel="noreferrer">Kịch bản UAT và nhật ký tiến độ kiểm thử</a> được đăng trên GitHub Gist.</p><h3 id="_2-2-tinh-trang-homelab" tabindex="-1">2.2. Tình trạng homelab <a class="header-anchor" href="#_2-2-tinh-trang-homelab" aria-label="Permalink to “2.2. Tình trạng homelab”">​</a></h3><p>Đang điền secrets và biến môi trường, đồng thời hoàn thiện config cho RustFS. Hệ thống <strong>chưa được triển khai và xác minh đầu cuối</strong> trên homelab.</p><h2 id="_3-ke-hoach-theo-tung-giai-đoan" tabindex="-1">3. Kế hoạch theo từng giai đoạn <a class="header-anchor" href="#_3-ke-hoach-theo-tung-giai-đoan" aria-label="Permalink to “3. Kế hoạch theo từng giai đoạn”">​</a></h2><h3 id="_3-1-giai-đoan-tiep-theo" tabindex="-1">3.1. Giai đoạn tiếp theo <a class="header-anchor" href="#_3-1-giai-đoan-tiep-theo" aria-label="Permalink to “3.1. Giai đoạn tiếp theo”">​</a></h3><ol><li>Hoàn tất config homelab và triển khai thử trên cụm Kubernetes; kiểm tra định tuyến, kiểm soát truy cập, tình trạng dịch vụ và quy trình nâng cấp.</li><li>Tiếp tục kiểm thử thanh toán, ưu tiên checkout trùng, phân quyền và khôi phục webhook. Sửa việc ghi dữ liệu nhạy cảm vào log và thu hồi phiên hoặc token bị ảnh hưởng.</li><li><strong>NestJS 12:</strong> Chuẩn bị nâng cấp, nhưng chỉ thực hiện khi có bản Nx ổn định tương thích. <a href="https://github.com/notopia-uit/notopia/pull/350" target="_blank" rel="noreferrer">https://github.com/notopia-uit/notopia/pull/350</a></li><li><strong>Native ESM:</strong> Đánh giá riêng việc chuyển đổi cho Document, AI và search-worker, nhất là thứ tự khởi tạo OpenTelemetry và các lệnh chạy trong container. <a href="https://github.com/notopia-uit/notopia/commit/7374de9f" target="_blank" rel="noreferrer">Kế hoạch kỹ thuật (<code>7374de9f</code>)</a></li><li><strong>TypeORM extension:</strong> Kiểm tra tương thích với TypeORM hiện tại, gồm lệnh CLI và dữ liệu mẫu. <a href="https://github.com/notopia-uit/notopia/pull/346" target="_blank" rel="noreferrer">https://github.com/notopia-uit/notopia/pull/346</a></li></ol><h3 id="_3-2-đinh-huong-dai-han" tabindex="-1">3.2. Định hướng dài hạn <a class="header-anchor" href="#_3-2-đinh-huong-dai-han" aria-label="Permalink to “3.2. Định hướng dài hạn”">​</a></h3><ul><li><strong>Nâng cấp BlockNote:</strong> Đánh giá việc chuyển từ <code>0.55</code> lên <code>0.57</code>, gồm thay đổi về ESM, DOM phía máy chủ và khả năng tương thích với Yjs. <a href="https://github.com/notopia-uit/notopia/pull/238" target="_blank" rel="noreferrer">https://github.com/notopia-uit/notopia/pull/238</a></li><li><strong>Demo lịch sử phiên bản:</strong> Tham khảo <a href="https://www.blocknotejs.org/examples/collaboration/versioning-yjs14" target="_blank" rel="noreferrer">demo lưu phiên bản với Yjs 14</a> và <a href="https://www.blocknotejs.org/examples/extensions/versioning" target="_blank" rel="noreferrer">demo tiện ích lịch sử phiên bản</a> của BlockNote. Mục tiêu là xem các tính năng này có đáp ứng nhu cầu lưu và khôi phục phiên bản tài liệu của Notopia hay không. Đây là các demo tham khảo, chưa được tích hợp vào Notopia.</li></ul>`,27)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};